typedef struct TCContext{TCDevice*d;HMODULE module;HWND window;UINT mode,expected,words,vertex_words;BOOL core;}TCContext;
static HRESULT bc_vb(TCContext*,UINT,DWORD,DWORD,UINT,TCVB**);static HRESULT bc_stream(TCContext*,TCVB*,UINT);static HRESULT bc_fvf(TCContext*,DWORD);static HRESULT bc_process(TCContext*,UINT,UINT,UINT,TCVB*,DWORD);static void bc_query_binding(TCContext*,TCVB*,UINT);static void tc_read(TCContext*);static HRESULT tc_reset(TCContext*);
static void tc_check(BOOL ok,const char*s){if(!ok){tc_report(s);ExitProcess(1);}}static void tc_expect(HRESULT hr,const char*s){tc_check(hr==D3D_OK,s);}
typedef struct{float x,y,z;DWORD color;}PVInput;typedef struct{float x,y,z,w;DWORD color;}PVOutput;
_Static_assert(sizeof(PVInput)==16&&sizeof(PVOutput)==20,"PV vertex layouts");
static const float pv_xy[6][2]={{-1.25f,1.25f},{1.25f,1.25f},{-1.25f,-1.25f},{-1.25f,-1.25f},{1.25f,1.25f},{1.25f,-1.25f}};
static void pv_source(void*data,DWORD color){PVInput*v=data;for(UINT n=0;n<8;n++)v[n]=(PVInput){99,99,.5f,0xffffff00u};for(UINT n=0;n<6;n++)v[n+1]=(PVInput){pv_xy[n][0],pv_xy[n][1],.5f,color};}
static void pv_output(TCContext*c,TCVB*v){BLockPointer data=NULL;tc_expect(BC_VLOCK(v,0,0,&data,16),"FAIL output readonly");for(UINT n=0;n<8;n++)for(UINT word=0;word<5;word++){DWORD got,wanted=0xccccccccu;CopyMemory(&got,(BYTE*)data+n*20+word*4,4);if(n>0&&n<7){PVOutput expected={(pv_xy[n-1][0]+1)*4,(1-pv_xy[n-1][1])*4,.5f,1,c->expected};CopyMemory(&wanted,(BYTE*)&expected+word*4,4);}tc_check(got==wanted,"FAIL CPU ProcessVertices output/padding");c->vertex_words++;}tc_expect(BC_VUNLOCK(v),"FAIL output readonly unlock");}
static void pv_setup(TCContext*c){tc_expect(TC_RS(c->d,7,0),"FAIL depth");tc_expect(TC_RS(c->d,137,0),"FAIL lighting");tc_expect(TC_RS(c->d,22,1),"FAIL cull");tc_expect(TC_RS(c->d,136,0),"FAIL clipping");tc_expect(TC_TSS(c->d,0,1,3),"FAIL colorop");tc_expect(TC_TSS(c->d,0,3,0),"FAIL colorarg");tc_expect(TC_TSS(c->d,0,4,3),"FAIL alphaop");tc_expect(TC_TSS(c->d,0,6,0),"FAIL alphaarg");}
static void tc_cases(TCContext*c){TCVB*source=NULL,*destination=NULL;UINT sfvf=c->mode==2?0x42:0x4042,dfvf=c->mode==2?0x44:0x4044;tc_expect(bc_vb(c,128,0,sfvf,1,&source),"FAIL source VB");tc_expect(bc_vb(c,160,0,dfvf,1,&destination),"FAIL destination VB");TCVBDesc desc;tc_expect(BC_VDESC(source,&desc),"FAIL source desc");tc_check(desc.Size==128&&desc.FVF==sfvf&&desc.Pool==1&&!desc.Usage,"FAIL source metadata");tc_expect(BC_VDESC(destination,&desc),"FAIL destination desc");tc_check(desc.Size==160&&desc.FVF==dfvf&&desc.Pool==1&&!desc.Usage,"FAIL destination metadata");TCDevice*parent=NULL;tc_expect(BC_VPARENT(source,&parent),"FAIL source parent");tc_check(parent==c->d,"FAIL source parent identity");TC_DREL(parent);tc_expect(BC_VPARENT(destination,&parent),"FAIL destination parent");tc_check(parent==c->d,"FAIL destination parent identity");TC_DREL(parent);BLockPointer data=NULL;tc_expect(BC_VLOCK(destination,0,0,&data,0),"FAIL destination init lock");for(UINT i=0;i<160;i++)((BYTE*)data)[i]=0xcc;tc_expect(BC_VUNLOCK(destination),"FAIL destination init upload");pv_setup(c);
 const DWORD colors[]={0xffff0000u,0xff0000ffu,0xff00ff00u,0xff8000ffu};
 for(UINT step=0;step<4;step++){if(step==3){tc_expect(tc_reset(c),"FAIL managed Reset");pv_setup(c);}tc_expect(BC_VLOCK(source,0,0,&data,0),"FAIL source lock");pv_source(data,colors[step]);tc_expect(BC_VUNLOCK(source),"FAIL source upload");tc_expect(bc_stream(c,source,16),"FAIL source stream");tc_expect(bc_fvf(c,0x4042),"FAIL source FVF8");bc_query_binding(c,source,16);
 if(step==0){tc_expect(BC_VLOCK(destination,0,0,&data,16),"FAIL guard destination lock");tc_check(bc_process(c,1,1,6,destination,0)==D3DERR_INVALIDCALL,"FAIL locked destination accepted");tc_expect(BC_VUNLOCK(destination),"FAIL guard destination unlock");tc_check(bc_process(c,1,1,0,destination,0)==D3DERR_INVALIDCALL,"FAIL zero count accepted");tc_check(bc_process(c,1,0xffffffffu,6,destination,0)==D3DERR_INVALIDCALL,"FAIL destination range accepted");tc_check(bc_process(c,0xffffffffu,1,6,destination,0)==D3DERR_INVALIDCALL,"FAIL source range accepted");tc_expect(BC_VLOCK(source,0,0,&data,16),"FAIL guard source lock");tc_check(bc_process(c,1,1,6,destination,0)==D3DERR_INVALIDCALL,"FAIL locked source accepted");tc_expect(BC_VUNLOCK(source),"FAIL guard source unlock");}
 tc_expect(bc_process(c,1,1,6,destination,step==1?1:0),"FAIL ProcessVertices");c->expected=step==1?colors[0]:colors[step];pv_output(c,destination);tc_expect(bc_stream(c,destination,20),"FAIL destination stream");tc_expect(bc_fvf(c,0x4044),"FAIL destination FVF8");bc_query_binding(c,destination,20);tc_expect(TC_CLEAR(c->d,0,NULL,1,0xff010203,1,0),"FAIL clear");tc_expect(TC_BEGIN(c->d),"FAIL begin");tc_expect(TC_DRAW(c->d,D3DPT_TRIANGLELIST,1,2),"FAIL processed draw");tc_expect(TC_END(c->d),"FAIL end");tc_read(c);char line[160];wsprintfA(line,"PROCCORE FRAME index=%u mode=%u step=%u copyData=%u vertexWords=40 readback=1",tc_frame_index++,c->mode,step,step!=1);tc_report(line);}
 tc_expect(bc_stream(c,NULL,0),"FAIL final stream clear");tc_check(!BC_VREL(source)&&!BC_VREL(destination),"FAIL final VB refs");char line[200];wsprintfA(line,"PROCCORE CHECK mode=%u guards=5 srcStart=1 dstIndex=1 stride=20 vertexWords=160 localWords=256 raw8bit14=1 reset=1 finalRefs=0",c->mode);tc_report(line);}
